DROP EXTERNAL FILE FORMAT ff_csv

DROP EXTERNAL table ta

CREATE EXTERNAL FILE FORMAT ff_csv
WITH (  
    FORMAT_TYPE = DELIMITEDTEXT,
    FORMAT_OPTIONS ( FIELD_TERMINATOR = ',', STRING_DELIMITER = '"', FIRST_ROW = 2 )
);

-- CREATE EXTERNAL FILE FORMAT ff_parquet WITH (  FORMAT_TYPE = PARQUET );

-- CREATE EXTERNAL FILE FORMAT ff_delta WITH (  FORMAT_TYPE = DELTA );

----------------------------------------

CREATE EXTERNAL TABLE ta
(
    STUDYID VARCHAR(200),
    DOMAIN VARCHAR(200),
    ARMCD VARCHAR(200),
    ARM VARCHAR(200),
    TAETORD INT,
    ETCD VARCHAR(200),
    ELEMENT VARCHAR(200)
)
WITH (
    LOCATION = 'synapse-files/clintrail_data_files/TA/TA.csv',
    DATA_SOURCE = ds_stsyn011_file_data,
    FILE_FORMAT = ff_csv
);


SELECT * FROM dbo.ta;

SELECT * FROM dbo.ta WHERE ARMCD = 'ARMA';

SELECT STUDYID,COUNT(*) AS cnt from ta GROUP BY STUDYID;

